using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using Mewgic;using Mewgic.Core;using Mewgic.Map;
public static class Part12BEditor
{
 const string Output="docs/ProductionReports/Part12B/";static readonly List<string> checks=new List<string>();static void Check(bool ok,string m){if(!ok)throw new Exception(m);checks.Add(m);}
 static ProgressData Data(int complete){var d=new ProgressData();d.worldMap.migrated=true;for(int i=1;i<=complete;i++)d.levels.Add(new LevelRecord{level=i,bestStars=i%3+1,rewardClaimed=true});return d;}
 public static void Models(){Directory.CreateDirectory(Output);checks.Clear();try{
  var def=MapProgressionCatalog.Definition();Check(def.expandable&&def.regions.Length==12,"12 ada ve genişletilebilir katalog");string[] names={"Enchanted Village","Crystal Falls","Moon Garden","Sky Castle"};for(int i=0;i<12;i++){Check(def.regions[i].firstLevel==i*50+1&&def.regions[i].levelCount==50,"Ardışık 50 bölüm: "+i);Check(def.regions[i].artReady==(i<4)&&def.regions[i].tutorialIds.Length==0,"Sanat durumu ve boş mekanik tetikleyicileri: "+i);if(i<4)Check(def.regions[i].displayName==names[i]&&def.regions[i].artIndex==i,"Özgün ada/sanat sırası: "+i);}
  foreach(int n in new[]{0,1,2,49,50,51,99,100,101,199,200,201,598,599,600,601,650}){var ledger=new ProgressLedger(Data(n),_=>{});var map=MapProgressionCatalog.Open(ledger);Check(map.CurrentId==n+1&&map.CurrentRegion==n/50,"Güncel bölüm/ada sınırı "+n);Check(map.CanEnter(n+1)&&!map.CanEnter(n+2),"Kilit sınırı "+n);if(n>0)Check(map.CanEnter(n)&&map.Stars(n)==n%3+1,"Yeniden oynama/yıldızlar "+n);for(int i=0;i<14;i++){Check(map.RegionOpen(i)==(i<=n/50),"Ada kilidi "+n+"/"+i);Check(map.Completed(i)==Math.Max(0,Math.Min(50,n-i*50)),"Ada tamamlanma "+n+"/"+i);}var again=MapProgressionCatalog.Open(new ProgressLedger(JsonUtility.FromJson<ProgressData>(JsonUtility.ToJson(ledger.Snapshot)),_=>{}));Check(again.CurrentId==map.CurrentId&&again.RegionOpen(n/50),"JSON sürekliliği "+n);}
  var fresh=new ProgressLedger(new ProgressData(),_=>{});var live=MapProgressionCatalog.Open(fresh);for(int i=1;i<=50;i++)fresh.Claim(i,3,true,out _);Check(live.CurrentId==51&&live.RegionOpen(1)&&live.ChestReady(0),"Canlı ilerleme ve 50. bölüm sandığı");Check(fresh.WorldMap.legacyChestEntitlements.Count==0,"Yeni oyuncuya eski 2. bölüm sandığı erken verilmez");int h=fresh.Remaining(BoosterKind.Hint);Check(live.ClaimChest(0,out bool granted)&&granted&&fresh.Remaining(BoosterKind.Hint)==h+1,"50 bölüm ödülü atomik");Check(live.ClaimChest(0,out granted)&&!granted&&fresh.Remaining(BoosterKind.Hint)==h+1,"Sandık tekrarı engellendi");
  var old=Data(11);old.worldMap=null;var legacy=new ProgressLedger(old,_=>{});var migrated=MapProgressionCatalog.Open(legacy);Check(legacy.WorldMap.legacyChestEntitlements.Count==4&&migrated.ChestReady(3)&&!migrated.RegionOpen(3),"Eski hak edilmiş, alınmamış dört sandık kilitten bağımsız korunur");old.claimedMilestones.Add("map.village.v1");var claimed=MapProgressionCatalog.Open(new ProgressLedger(old,_=>{}));Check(claimed.ChestClaimed(0)&&!claimed.ChestReady(0),"Eski alınmış sandık aynı kimlikte korunur");var fail=new ProgressLedger(old,_=>throw new IOException("QA"));int balance=fail.Remaining(BoosterKind.Hint);Check(!MapProgressionCatalog.Open(fail).ClaimChest(1,out granted)&&!granted&&fail.Remaining(BoosterKind.Hint)==balance&&!fail.MilestoneClaimed("map.crystal.v1"),"Başarısız save ödülü tüketmez");Check(!fail.SaveMapFocus(601)&&fail.WorldMap.lastFocusedLevel==1,"Başarısız odak kaydı atomik");
  var gap=Data(100);gap.levels.RemoveAll(x=>x.level==49);var gapMap=MapProgressionCatalog.Open(new ProgressLedger(gap,_=>{}));Check(gapMap.CurrentId==49&&!gapMap.CanEnter(51)&&!gapMap.ChestReady(1),"Eksik önkoşul kilidi atlatmaz");
  for(int id=1;id<=1000;id++)Check(WorldMapRules.FirstLevel(WorldMapRules.Island(id))<=id&&WorldMapRules.FirstLevel(WorldMapRules.Island(id))+49>=id,"Bölüm-ada dönüşümü "+id);
  foreach(int id in new[]{51,101,151,201,551,601,651}){Check(WorldMapRules.Request(id).target==LevelDifficulty.Easy,"Yeni ada girişi Easy "+id);Check(WorldMapRules.Request(id+1).target==LevelDifficulty.Normal&&WorldMapRules.Request(id+2).target==LevelDifficulty.Normal,"Yumuşak ilk üç bölüm "+id);}Check(WorldMapRules.Request(50).target==GeneratorRequest.ForLevel(50).target&&WorldMapRules.Request(54).target==GeneratorRequest.ForLevel(54).target,"Giriş dışı 12A temposu aynı");
  var bad=MapProgressionCatalog.Definition();bad.regions[1].firstLevel=50;bool rejected=false;try{new MapProgression(bad,fresh,_=>true);}catch(ArgumentException){rejected=true;}Check(rejected,"Çakışan ada aralığı reddedilir");bad=MapProgressionCatalog.Definition();bad.regions[1].reward.id=bad.regions[0].reward.id;rejected=false;try{new MapProgression(bad,fresh,_=>true);}catch(ArgumentException){rejected=true;}Check(rejected,"Çift ödül kimliği reddedilir");
  GameplayBoosterTests.ModelTests();Check(true,"Mevcut şişe/Undo/Hint/Shuffle model regresyonu");File.WriteAllText(Output+"MODEL_TESTS.json",Newtonsoft.Json.JsonConvert.SerializeObject(new{success=true,count=checks.Count,checks},Newtonsoft.Json.Formatting.Indented));
 }catch(Exception e){File.WriteAllText(Output+"MODEL_TESTS.json",Newtonsoft.Json.JsonConvert.SerializeObject(new{success=false,count=checks.Count,error=e.ToString(),checks},Newtonsoft.Json.Formatting.Indented));throw;}}
 public static void Run(){if(EditorApplication.isPlaying)throw new Exception("Play Mode durdurulmalı");Models();SessionState.SetString("Part12B.Key","Mewgic.Tests.Part12B."+Guid.NewGuid().ToString("N"));SessionState.SetString("Part12B.Archive",Path.Combine(Path.GetTempPath(),"Mewgic-Part12B-QA-"+Guid.NewGuid().ToString("N")));EditorSceneManager.OpenScene("Assets/Scenes/LevelMap.unity");new GameObject("PART12B QA").AddComponent<Part12BProbe>();Size(1600);EditorApplication.isPlaying=true;}
 public static void Preview(){if(EditorApplication.isPlaying)throw new Exception("Play Mode durdurulmalı");EditorSceneManager.OpenScene("Assets/Scenes/LevelMap.unity");new GameObject("PART12B Safe Preview").AddComponent<Part12BProbe>().preview=true;Size(1600);EditorApplication.isPlaying=true;}
 public static void Size(int height){var a=typeof(Editor).Assembly;var type=a.GetType("UnityEditor.GameViewSizes");var sizes=typeof(ScriptableSingleton<>).MakeGenericType(type).GetProperty("instance").GetValue(null);var groupType=type.GetProperty("currentGroupType",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.Public|System.Reflection.BindingFlags.NonPublic).GetValue(sizes);var group=type.GetMethod("GetGroup").Invoke(sizes,new[]{groupType});var kind=a.GetType("UnityEditor.GameViewSizeType");var size=Activator.CreateInstance(a.GetType("UnityEditor.GameViewSize"),new object[]{Enum.ToObject(kind,1),900,height,"PART12B 900x"+height});group.GetType().GetMethod("AddCustomSize").Invoke(group,new[]{size});int count=(int)group.GetType().GetMethod("GetTotalCount").Invoke(group,null);var window=EditorWindow.GetWindow(a.GetType("UnityEditor.GameView"));window.GetType().GetProperty("selectedSizeIndex",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.Public|System.Reflection.BindingFlags.NonPublic).SetValue(window,count-1);window.Focus();}
}
